@js:
var b = String(baseUrl||"");
if (b.indexOf("audiobook.php") < 0) { result = ""; } else {
  function getParam(u,k){var m=String(u||"").match(new RegExp("[?&]"+k+"=([^&]*)"));return m?decodeURIComponent(m[1]):"";}
  function fmtLrc(ms){
    var t=Math.max(0,Math.floor(Number(ms||0)));
    var m=Math.floor(t/60000);
    var s=Math.floor((t%60000)/1000);
    var c=Math.floor((t%1000)/10);
    return "["+(m<10?"0":"")+m+":"+(s<10?"0":"")+s+"."+(c<10?"0":"")+c+"]";
  }
  var plat=getParam(b,"platform");
  var albumId=getParam(b,"album_id");
  var chapterId=getParam(b,"chapter_id");
  var capUrl="https://zenneko.top/api/audiobook.php?action=caption&platform="+plat+"&album_id="+albumId+"&chapter_id="+chapterId;
  var cj={}; try{cj=JSON.parse(java.ajax(capUrl)||"{}");}catch(e){cj={};}
  var lines=(cj.data&&cj.data.lines)||[];
  var out=[];
  for(var i=0;i<lines.length;i++){
    var ln=lines[i]||{};
    var txt=String(ln.text||"").trim();
    if(txt) out.push(fmtLrc(ln.start_time)+txt);
  }
  result=out.join("\n");
}

