jsLib:
function nhSetVariable(value) {
    var s = nhSource.call(this);
    try {
        if (s.setVariable) {
            s.setVariable(String(value));
            return;
        }
    } catch (e) {}
    try {
        s.putVariable(String(value));
    } catch (e) {}
}

var NOVELHUB_VERSION = "2.25";

function nhSource() {
    try {
        if (this && this.source) return this.source;
    } catch (e) {}
    return source;
}

function nhJava() {
    try {
        if (this && this.java) return this.java;
    } catch (e) {}
    return java;
}

function nhCookie() {
    try {
        if (this && this.cookie) return this.cookie;
    } catch (e) {}
    try {
        return cookie;
    } catch (e) {
        return null;
    }
}

function nhParse(value) {
    if (value && typeof value == "object") return value;
    try {
        return JSON.parse(String(value || "{}"));
    } catch (e) {
        return {};
    }
}

function nhQuery(url, key) {
    var match = String(url || "").match(new RegExp("[?&]" + key + "=([^&]*)"));
    if (!match) return "";
    try {
        return decodeURIComponent(match[1]);
    } catch (e) {
        return match[1];
    }
}

function nhEncode(value) {
    var j = nhJava.call(this);
    try {
        return String(j.encodeURI(String(value == null ? "" : value)));
    } catch (e) {}
    return encodeURIComponent(String(value == null ? "" : value));
}

function nhLoginInfo() {
    try {
        return nhSource.call(this).getLoginInfoMap() || {};
    } catch (e) {
        return {};
    }
}

function nhConfig() {
    var config = {
        source: "qidian",
        mediaType: "novel",
        searchTab: 1,
        toneId: 1,
        api: "v2",
        aggregateSources: "qidian,menxige"
    };
    var saved = {};
    try {
        saved = nhParse(nhSource.call(this).getVariable());
    } catch (e) {}

    if (saved && typeof saved == "object" && !Array.isArray(saved)) {
        if (saved.source) config.source = String(saved.source);
        if (saved.mediaType) config.mediaType = String(saved.mediaType);
        if (saved.searchTab != null) config.searchTab = Number(saved.searchTab);
        if (saved.toneId != null) config.toneId = Number(saved.toneId);
        if (saved.tone_id != null) config.toneId = Number(saved.tone_id);
        if (saved.api) config.api = String(saved.api);
        if (saved.aggregateSources) config.aggregateSources = String(saved.aggregateSources);
        if (saved.sources) config.aggregateSources = String(saved.sources);
        if (saved.mode) {
            config.mediaType = String(saved.mode)
                .replace("小说", "novel")
                .replace("漫画", "comic")
                .replace("听书", "audio")
                .replace("短剧", "video");
        }
    }

    var login = nhLoginInfo.call(this);
    if (login["音色 ID"] != null) {
        config.toneId = Number(login["音色 ID"]) || config.toneId;
    }
    if (config.mediaType == "comic") config.searchTab = 2;
    if (config.mediaType == "audio") config.searchTab = 3;
    if (config.mediaType == "video") config.searchTab = 4;
    return config;
}

function Config() {
    return nhConfig.call(this);
}

function novelHubDevice() {
    var j = nhJava.call(this);
    var device = "";
    try {
        device = String(j.androidId() || "");
    } catch (e) {}
    if (!device) {
        try {
            device = String(j.randomUUID() || "");
        } catch (e) {}
    }
    return device;
}

function getSessionId() {
    var c = nhCookie.call(this);
    var value = "";
    try {
        value = String(c.getKey("fanqienovel.com", "sessionid") || "");
    } catch (e) {}
    if (!value) {
        try {
            value = String(nhSource.call(this).get("fanqie_cookie") || "");
        } catch (e) {}
    }
    return value;
}

function novelHubHeaders() {
    var j = nhJava.call(this);
    var headers = {
        version: NOVELHUB_VERSION,
        "X-device": novelHubDevice.call(this),
        "X-User-Agent": String(j.getWebViewUA ? j.getWebViewUA() : "Android")
    };
    var sessionId = getSessionId.call(this);
    if (sessionId) headers.sessionid = sessionId;
    return JSON.stringify(headers);
}

function novelHubSearchTab(config) {
    var mediaType = String(config && (config.mode || config.mediaType) || "novel");
    if (mediaType == "comic") return 2;
    if (mediaType == "audio") return 3;
    if (mediaType == "video") return 4;
    return Number(config && config.searchTab) || 1;
}

function novelHubMediaType(item, config) {
    var data = nhParse(item);
    var rawType = String(data.book_type || data.bookType || data.type || data.mode || "").toLowerCase();
    if (rawType == "video" || rawType == "4" || rawType == "128") return "video";
    if (rawType == "audio" || rawType == "32") return "audio";
    if (rawType == "comic" || rawType == "image" || rawType == "64") return "comic";
    return String(config && config.mediaType || "novel");
}

function novelHubBookType(mediaType) {
    if (mediaType == "video") return 4;
    if (mediaType == "audio") return 32;
    if (mediaType == "comic") return 64;
    return 8;
}

function buildNovelHubSearchUrl(key, page, config) {
    config = config || nhConfig.call(this);
    var sourceName = String(config.source || "qidian");
    var path = sourceName == "aggregate" ? "/api/search/aggregate" : "/api/search/" + sourceName;
    var params = [];
    if (sourceName == "fanqie") {
        params.push("searchTab=" + novelHubSearchTab(config));
    }
    params.push("offset=" + (Number(page) || 1));
    params.push("query=" + nhEncode.call(this, key));
    if (sourceName == "aggregate") {
        params.push("sources=" + nhEncode.call(this, config.aggregateSources || "qidian,menxige"));
    }
    return nhSource.call(this).getKey() + path + "?" + params.join("&");
}

function buildNovelHubBookUrl(item) {
    var data = nhParse(item);
    var config = nhConfig.call(this);
    var sourceName = String(data.source || config.source || "qidian");
    var mediaType = novelHubMediaType.call(this, data, config);
    var bookId = String(data.book_id || data.bid || data.id || "");
    return nhSource.call(this).getKey() + "/api/detail/" + sourceName + "/" + bookId + "?mediaType=" + mediaType;
}

function buildNovelHubTocUrl(item) {
    var data = nhParse(item);
    var config = nhConfig.call(this);
    var sourceName = String(data.source || config.source || "qidian");
    var mediaType = novelHubMediaType.call(this, data, config);
    return nhSource.call(this).getKey() + "/api/chapterlist/" + sourceName + "/" + String(data.book_id || "") + "?mediaType=" + mediaType + "&tone_id=" + config.toneId + "&api=" + config.api;
}

function buildNovelHubChapterUrl(item, catalogUrl) {
    var chapter = nhParse(item);
    var match = String(catalogUrl || "").match(/\/api\/chapterlist\/([^\/]+)\/([^?\/]+)/);
    var sourceName = match ? match[1] : "qidian";
    var bookId = match ? match[2] : "";
    var mediaType = nhQuery(catalogUrl, "mediaType") || "novel";
    var toneId = nhQuery(catalogUrl, "tone_id") || nhConfig.call(this).toneId;
    var api = nhQuery(catalogUrl, "api") || nhConfig.call(this).api;
    var chapterId = String(chapter.item_id || "");
    var path;
    if (mediaType == "novel") {
        path = "/api/content/" + sourceName + "/" + bookId + "/" + chapterId;
    } else {
        path = "/api/content/" + sourceName + "/" + mediaType + "/" + bookId + "/" + chapterId + "?tone_id=" + toneId + "&api=" + api;
    }
    return nhSource.call(this).getKey() + path;
}

function novelHubOpenVideo(data, contentUrl) {
    data = nhParse(data);
    var sourceName = String(data.source || nhQuery(contentUrl, "source") || "fanqie");
    var bookId = String(data.novelId || nhQuery(contentUrl, "book_id") || "");
    var url = nhSource.call(this).getKey() + "/book?src=" + sourceName + "&id=" + bookId + "&mode=video";
    nhJava.call(this).startBrowser(url, String(data.title || "短剧播放"));
    return "短剧已在浏览器打开";
}

function parseNovelHubContent(raw, contentUrl) {
    var root = nhParse(raw);
    var data = root.data || {};
    var mediaType = String(data.bookTypeName || "").toLowerCase();
    if (!mediaType) {
        mediaType = String(data.bookType) == "32" ? "audio" : String(data.bookType) == "64" ? "comic" : String(data.bookType) == "4" ? "video" : (nhQuery(contentUrl, "mediaType") || "novel");
    }
    if (mediaType == "video") return novelHubOpenVideo.call(this, data, contentUrl);
    if (Number(root.code) != 200 && !data.content && !data.resources) return String(root.message || "正文获取失败");
    if (mediaType == "audio") {
        var audioResources = Array.isArray(data.resources) ? data.resources : [];
        for (var i = 0; i < audioResources.length; i++) {
            if (String(audioResources[i].type || "") == "audio") return String(audioResources[i].original_url || audioResources[i].url || "");
        }
        return String(data.content || "");
    }
    if (mediaType == "comic") {
        var imageResources = Array.isArray(data.resources) ? data.resources : [];
        var images = [];
        for (var j = 0; j < imageResources.length; j++) {
            if (String(imageResources[j].type || "") == "image") images.push("<img src=\"" + String(imageResources[j].original_url || imageResources[j].url || "") + "\">");
        }
        return images.join("\n");
    }
    return String(data.content || "").replace(/\r\n?/g, "\n");
}

function novelHubCacheBook() {
    var j = nhJava.call(this);
    var sourceObject = nhSource.call(this);
    var login = nhLoginInfo.call(this);
    var bookUrl = "";
    try {
        bookUrl = String(book.bookUrl || "");
    } catch (e) {}
    var match = bookUrl.match(/\/api\/detail\/([^\/]+)\/([^?\/]+)/);
    var sourceName = match ? match[1] : String(login["缓存来源"] || "qidian");
    var bookId = match ? match[2] : String(login["缓存书籍ID"] || "");
    if (!bookId) {
        j.toast("请填写缓存书籍 ID，或从书籍详情页打开此按钮");
        return;
    }
    try {
        var raw = j.ajax(sourceObject.getKey() + "/api/cache/" + sourceName + "/" + bookId + "," + JSON.stringify({
            method: "POST",
            headers: nhParse(novelHubHeaders.call(this))
        }));
        var response = nhParse(raw);
        j.toast(response.message || "缓存任务已提交");
    } catch (e) {
        j.longToast("缓存任务提交失败：" + String(e));
    }
}

function novelHubTones(sourceName, bookId) {
    var j = nhJava.call(this);
    try {
        var raw = j.ajax(nhSource.call(this).getKey() + "/api/audio/tones/" + sourceName + "/" + bookId + "," + JSON.stringify({
            method: "GET",
            headers: nhParse(novelHubHeaders.call(this))
        }));
        var tones = nhParse(raw).data && nhParse(raw).data.tones || [];
        var output = [];
        for (var i = 0; i < tones.length; i++) output.push(String(tones[i].id || "") + ":" + String(tones[i].title || tones[i].name || ""));
        return output.join(", ");
    } catch (e) {
        return "";
    }
}

function novelHubShowTones() {
    var j = nhJava.call(this);
    var login = nhLoginInfo.call(this);
    var bookUrl = "";
    try {
        bookUrl = String(book.bookUrl || "");
    } catch (e) {}
    var match = bookUrl.match(/\/api\/detail\/([^\/]+)\/([^?\/]+)/);
    var sourceName = match ? match[1] : String(login["缓存来源"] || "fanqie");
    var bookId = match ? match[2] : String(login["缓存书籍ID"] || "");
    if (!bookId) {
        j.toast("请填写听书书籍 ID");
        return;
    }
    j.longToast(novelHubTones.call(this, sourceName, bookId) || "该书暂无音色数据");
}

function novelHubSetSource(sourceName) {
    var config = nhConfig.call(this);
    config.source = String(sourceName);
    nhSetVariable.call(this, JSON.stringify(config));
    nhJava.call(this).toast("已切换来源：" + config.source);
}

function novelHubSetMode(mediaType) {
    var config = nhConfig.call(this);
    config.mediaType = String(mediaType);
    nhSetVariable.call(this, JSON.stringify(config));
