        var root;
        try {
            root = nhParse(nhJava.call(this).ajax(url));
        } catch (e) {
            root = {};
        }
        var category = root.data && root.data.category_tab_data;
        if (!category) continue;
        add("====== " + String(category.tab_name || "番茄分类") + " ======", "", 1);
        var cells = Array.isArray(category.cell_data) ? category.cell_data : [];
        for (var j = 0; j < cells.length; j++) {
            var cell = cells[j] || {};
            var atoms = Array.isArray(cell.atom_data) ? cell.atom_data : [];
            var first = atoms[0] && atoms[0].category_data;
            if (!first || !first.category_id) continue;
            var landing = categoryHost + "/reading/bookapi/new_category/landing/v/?"
                + "category_id=" + first.category_id
                + "&limit=20&offset={{(page-1)*20}}"
                + "&gender=" + tab.gender + "&genre=" + tab.genre;
            add(String(cell.cell_name || first.name || "分类"), landing, 1);
            for (var k = 1; k < atoms.length; k++) {
                var child = atoms[k] && atoms[k].category_data;
                if (!child || !child.category_id) continue;
                add(String(child.name || "子分类"), categoryHost + "/reading/bookapi/new_category/landing/v/?"
                    + "category_id=" + child.category_id
                    + "&limit=20&offset={{(page-1)*20}}"
                    + "&gender=" + tab.gender + "&genre=" + tab.genre, 0.25);
            }
        }
    }

    add("🔎 聚合搜索", host + "/api/search/aggregate?offset={{page}}&query={{key}}&sources=qidian%2Cmenxige", 1);
    return JSON.stringify(output);
}

function novelHubExploreBooks(raw, baseUrl) {
    var root = nhParse(raw);
    var found = [];
    var seen = {};

    function visit(value) {
        if (!value) return;
        if (Array.isArray(value)) {
            for (var i = 0; i < value.length; i++) visit(value[i]);
            return;
        }
        if (typeof value != "object") return;
        var book = value.book_data && value.book_data[0] || value;
        var id = book.book_id || book.book_id_str || book.id;
        var name = book.book_name || book.book_title || book.name || book.title;
        if (id && name && !seen[String(id)]) {
            seen[String(id)] = true;
            var sourceName = String(book.source || "fanqie");
            var mediaType = novelHubMediaType.call(this, book, { mediaType: "novel" });
            found.push({
                name: String(name),
                author: String(book.author || book.author_name || ""),
                bookUrl: nhSource.call(this).getKey() + "/api/detail/" + sourceName + "/" + String(id) + "?mediaType=" + mediaType,
                coverUrl: String(book.thumb_url || book.cover || book.cover_url || ""),
                intro: String(book.abstract || book.intro || book.description || ""),
                kind: String(book.tags || book.category || ""),
                lastChapter: String(book.last_update_title || book.sub_title || ""),
                wordCount: String(book.word_number || book.word_count || "")
            });
        }
        for (var key in value) {
            if (key != "book_data") visit.call(this, value[key]);
        }
    }

    visit.call(this, root);
    return found;
}

function login() {
    Config.call(this);
}

