function bypass(result) {
    var url = result.url(), src = result.body(), code = result.code();
    var isBlocked = false;
    if (code === 502 || code === 403 || code === 503 || code === 429) isBlocked = true;
    if (src && (src.match(/Just a moment|Checking your browser|DDoS protection|小黄云|cf-browser-verification/i))) isBlocked = true;
    if (!isBlocked) return result;
    var lockKey = 'cf_verify_' + source.getKey();
    if (cache.get(lockKey)) {
        java.toast('等待验证完成...');
        while (cache.get(lockKey)) {
            java.lang.Thread.sleep(500);
        }
        return java.connect(url);
    }
    cache.put(lockKey, '1', 30000);
    try {
        var rootUrl = url.match(/https?:\/\/[^\/]+/)[0];
        var rootVerified = false;
        try {
            var rootResp = java.connect(rootUrl);
            if (rootResp.body().match(/Just a moment|Checking your browser|小黄云|cf-browser-verification/i)) {
                java.toast('正在验证根域...');
                java.startBrowserAwait(rootUrl, '验证根域');
                rootVerified = true;
            }
        } catch(e) {}
        if (!rootVerified) {
            java.toast('what can i say，曼巴 out');
            java.startBrowserAwait(url, '验证');
        }
        return java.connect(url);
    } finally {
        cache.delete(lockKey);
    }
}
