exploreUrl:
@js:
function began() {
  var host = String(source.bookSourceUrl || '').trim().replace(/\/+$/, '');
  if (!/^https?:\/\//i.test(host)) host = '';
  source.setVariable(JSON.stringify({
    'sytj_type': '', 'sytj_title': '', "频道": "男频", "bd_id": 2, "tone": "tone_id=0",
    "server_id": 0, "server": host, "hosts": host ? [host] : [], "api_key": "", "type": "小说模式", "module": 3,
    "showPara": true, "showChap": true, "showAuthor": true, "showBook": true, "showGod": true, "tone_cn": ""
  }, null, '\t'));
  java.toast('已初始化源变量！');
}

// ===== 初始化 =====
var sourceConfigReady = false;
try {
  var sourceConfig = JSON.parse(source.getVariable() || '{}');
  sourceConfigReady = !!sourceConfig && typeof sourceConfig === 'object' && !Array.isArray(sourceConfig);
} catch (e) {}
if (!sourceConfigReady) {
  java.toast('检测到异常源变量，正在重新初始化');
  began();
}

let arr = [],
    个人中心 = 1;

// === 工具函数 ===
let _zwf = "※";
let numx = 3;

function push(title, url, num, g, action) {
  let j = {
    title: title,
    url: url,
    style: {
      layout_flexGrow: g == 0 ? g : 1,
      layout_flexBasisPercent: num
    }
  };
  if (action) {
    j.action = action.action;
    j.name = action.name;
    j.type = action.type;
    j.chars = action.chars;
    j.viewName = action.viewName;
    j.default = action.default;
  }
  arr.push(j);
}

function zwf(len, cols, num) {
  if (len % cols !== 0) {
    let count = cols - len % cols;
    for (let i = 0; i < count; i++) {
      push(_zwf, '', num, 1, {
        "type": "button",
        "action": "java.toast('这是占位符')"
      });
    }
  }
}

function infoValue(name, fallback) {
  try {
    if (typeof infoMap !== 'undefined' && infoMap) {
      var value = infoMap[name];
      if ((value === undefined || value === null || value === '') && infoMap.get) value = infoMap.get(name);
      if (value !== undefined && value !== null && value !== '') return String(value);
    }
  } catch (e) {}
  return fallback;
}

function schemaValue(schema, name) {
  var match = String(schema || '').match(new RegExp('[?&]' + name + '=([^&]+)', 'i'));
  if (!match) return '';
  try { return decodeURIComponent(match[1]); } catch (e) { return match[1]; }
}

function categoryParams(atom, genreOverride) {
  atom = atom || {};
  var schema = String(atom.category_landpage_url || '');
  return {
    categoryId: schemaValue(schema, 'categoryId') || String(atom.category_id || ''),
    subCategoryIds: schemaValue(schema, 'subCategoryIds'),
    genreType: genreOverride || schemaValue(schema, 'genreType'),
    gender: schemaValue(schema, 'gender')
  };
}

function categoryUrl(params) {
  if (!params.categoryId) return '';
  var path = '/api/landing?category_id=' + encodeURIComponent(params.categoryId);
  if (params.subCategoryIds) path += '&sub_category_ids=' + encodeURIComponent(params.subCategoryIds);
  if (params.genreType) path += '&genre_type=' + encodeURIComponent(params.genreType);
  if (params.gender) path += '&gender=' + encodeURIComponent(params.gender);
  path += '&offset={{(page-1)*10}}';
  return API.call(this, path);
}

function loadCategoryFile(fileIndex, genreOverride) {
  try {
    var root = requestJSON.call(this, '/sy/' + fileIndex + '.json');
    var tabData = root.data && root.data.category_tab_data || {};
    var cells = tabData.cell_data || [];
    cells.forEach(function(cell) {
      var atoms = cell.atom_data || [];
      if (!atoms.length) return;
      var first = atoms[0].category_data || {};
      push(cell.cell_name || first.name || '分类', categoryUrl.call(this, categoryParams(first, genreOverride)), 1, 1, {});
      for (var i = 1; i < atoms.length; i++) {
        var atom = atoms[i].category_data || {};
        var url = categoryUrl.call(this, categoryParams(atom, genreOverride));
        if (url && atom.name) push(atom.name, url, 0.25, 1, {});
      }
      zwf(Math.max(0, atoms.length - 1), numx, 0.25);
    }, this);
  } catch (e) {
    java.log('分类文件 ' + fileIndex + ' 加载失败：' + e);
    push('分类加载失败，请刷新发现页', '', 1, 1, {});
  }
}

function getBdUrl(tab, id, rankSubId) {
  var path = '/api/bookmall/cell/change?offset={{(page-1)*10}}&genre_tab=' + encodeURIComponent(tab) + '&algo_type=' + encodeURIComponent(id);
  if (rankSubId) path += '&rank_sub_info_id=' + encodeURIComponent(rankSubId);
  return API.call(this, path);
}


function personalizedTabURL(index) {
  var sid = '';
  try { sid = String((this.cookie && this.cookie.getKey) ? this.cookie.getKey('fanqienovel.com', 'sessionid') : ''); } catch (eP1) {}
  try {
    if (!sid && (this.source && this.source.getLoginInfoMap)) {
      var sim = this.source.getLoginInfoMap() || {};
      sid = String(sim['手动登录Token'] || sim.get && sim.get('手动登录Token') || '');
    }
  } catch (eP2) {}
  sid = String(sid || '').trim();
  if (!sid) return '';
  var path = '/api/bookmall/tab?tab_index=' + encodeURIComponent(String(index)) + '&offset={{(page-1)*10}}&limit=100&sessionid=' + encodeURIComponent(sid);
  var mode = String(GET.call(this, 'type') || '小说模式');
  var channel = String(GET.call(this, '频道') || '');
  if ((mode == '小说模式' || mode == '短篇模式') && (channel == '男频' || channel == '女频')) {
    path += '&gender=' + encodeURIComponent(channel == '女频' ? '0' : '1');
  }
  return API.call(this, path);
}

// ==== 登录番茄 (个人中心) ====
var sessionid = '';
try { sessionid = String(cookie.getKey('fanqienovel.com', 'sessionid') || (source.getLoginInfoMap() || {})['手动登录Token'] || '').trim(); } catch (e) {}
if (sessionid) {
  try {
    var userRoot = requestJSON.call(this, '/api/book_user?sessionid=' + encodeURIComponent(sessionid));
    var username = userRoot.data && (userRoot.data.name || userRoot.data.user_name || userRoot.data.screen_name) || '我的';
    push(username + '的个人中心', '', 1, 1, {});
    push('首页推荐', personalizedTabURL.call(this, 0), 0.4, 1, {});
    push('猜你喜欢', personalizedTabURL.call(this, 2), 0.4, 1, {});
    push('我的书架', API.call(this, '/api/book_shelf?sessionid=' + encodeURIComponent(sessionid) + '&page={{page}}&limit=20'), 0.4, 1, {});
    try {
      var _bookShelfGroups = requestJSON.call(this, '/api/book_shelf?groups_only=1&sessionid=' + encodeURIComponent(sessionid));
      var _groupArr = (_bookShelfGroups.data && _bookShelfGroups.data.groups) || [];
      for (var _gi = 0; _gi < _groupArr.length; _gi++) {
        push('书架·' + String(_groupArr[_gi].name || '未分组') + '（' + Number(_groupArr[_gi].count || 0) + '）', API.call(this, '/api/book_shelf?group=' + encodeURIComponent(String(_groupArr[_gi].name || '未分组')) + '&sessionid=' + encodeURIComponent(sessionid) + '&page={{page}}&limit=20'), 0.25, 1, {});
      }
    } catch (eG) { java.log('书架分组加载失败：' + eG); }
    push('阅读历史', API.call(this, '/api/read_history?sessionid=' + encodeURIComponent(sessionid) + '&ys_module=' + encodeURIComponent(((getModuleMap()[GET('type') || '小说模式'] || {module:3}).module || 3)) + '&page={{page}}&limit=20'), 0.4, 1, {});
  } catch (e) { java.log(e); }
}

// ===== 模式 =====
let types = ['小说模式', '听书模式', '漫画模式', '短剧模式', '短篇模式', '漫剧模式'];
push('模式', '', 0.4, 1, {
  "type": "select",
  "chars": types,
  "default": GET('type') || '小说模式',
  "action": "SET('type', infoMap['模式'] || (infoMap.get && infoMap.get('模式')) || '小说模式');java.refreshExplore()"
});

let selectedMode = GET('type') || infoValue('模式', '小说模式');
let modeMap = (getModuleMap())[selectedMode];
if (!modeMap) {
  selectedMode = '小说模式';
  modeMap = (getModuleMap())[selectedMode];
}
SET('module', modeMap.module);
SET('type', selectedMode);

// 小说和短篇保留男女频道；小说还支持出版分类。
let channel = infoValue('频道', GET('频道') || '男频');
if (selectedMode == '小说模式' || selectedMode == '短篇模式') {
  let channels = selectedMode == '小说模式' ? ['男频', '女频', '出版'] : ['男频', '女频'];
  if (channels.indexOf(channel) < 0) channel = '男频';
  push('频道', '', 0.4, 1, {
    "type": "select",
    "chars": channels,
    "default": channel,
    "action": "SET('频道', infoMap['频道'] || (infoMap.get && infoMap.get('频道')));java.refreshExplore()"
  });
  SET('频道', channel);
}

var genreTabMap = {'小说模式':'2','听书模式':'6','短剧模式':'4','短篇模式':'7','漫剧模式':'5'};
var genreTab = genreTabMap[selectedMode] || '';
if (selectedMode == '小说模式' && channel == '出版') genreTab = '3';
SET('bd_id', genreTab || modeMap.bd_id);

// ===== 首页推荐 =====
var homePresets = {
  '小说模式': channel == '出版' ? [[11,'经典'],[12,'知识']] : [[2,'推荐'],[25,'完本'],[31,'新书']],
  '听书模式': [[5,'听书推荐']],
  '漫画模式': [],
  '短剧模式': [[8,'短剧推荐'],[16,'热播']],
  '短篇模式': [[103,'短篇推荐']],
  '漫剧模式': [[24,'漫剧推荐']]
};
var homes = homePresets[selectedMode] || [];
push('【' + selectedMode + '导航】', '', 1, 1, {});
// v41：首页推荐和猜你喜欢已在登录个人中心使用 bookmall/tab tab/0、tab/2。

// ===== 官方榜单 =====
try {
if (genreTab) {
  let categorys = getCategorys();
  let categoryGroup = categorys[genreTab];
  let subItems = categoryGroup && categoryGroup.sub_items ? categoryGroup.sub_items : [];
  subItems.forEach(function(item) {
    push(item.show_name, getBdUrl.call(this, genreTab, item.selector_item_id, ''), 0.25, 1, {});
  }, this);
  zwf(subItems.length, numx, 0.25);
}
} catch (e) {
  java.log('榜单加载失败：' + e);
}

// ===== 精细分类 =====
if (selectedMode == '小说模式') {
  if (channel == '出版') {
    try {
      var categoryRoot = requestJSON.call(this, '/api/category');
      var publishCategories = categoryRoot.data && categoryRoot.data.publish_category || [];
      publishCategories.forEach(function(item) {
        var url = API.call(this, '/api/category/books?offset={{(page-1)*10}}&limit=10&creation_status=9&word_count=9&category_id=' + encodeURIComponent(item.category_id) + '&genre_type=160');
        push(item.category_name, url, 0.25, 1, {});
      }, this);
      zwf(publishCategories.length, numx, 0.25);
    } catch (e) { java.log('出版分类加载失败：' + e); }
  } else {
    loadCategoryFile.call(this, channel == '女频' ? 1 : 2, '');
  }
} else if (selectedMode == '听书模式') {
  loadCategoryFile.call(this, 4, '1');
} else if (selectedMode == '漫画模式') {
  loadCategoryFile.call(this, 5, '110');
} else if (selectedMode == '短剧模式') {
