// 登录及登录检查
function loginBubble() {
  java.startBrowser("https://syiism.cc.cd/bubble-community/", '');
}

function openBubblePreview() {
  var previewCustom = '';
  try { var pc = source.getLoginInfoMap().get('自定义SVG'); if (pc && pc != '' && String(pc).indexOf('<svg') >= 0) previewCustom = String(pc); } catch (e) {}
  var previewCommunity = '';
  try { var pv = JSON.parse(source.getVariable() || '{}'); if (pv && pv.bbSvg && String(pv.bbSvg).indexOf('<svg') >= 0) previewCommunity = String(pv.bbSvg); } catch (e) {}
  java.startBrowser(API.call(this, '/api/booksource?format=bubble&custom=' + encodeURIComponent(previewCustom) + '&community=' + encodeURIComponent(previewCommunity)), '气泡效果预览');
}

function syncCommunityBubble() {
  try {
    var communityBubble = java.ajax('https://syiism.cc.cd/bubble-community/api/bubbles/get-bubble');
    if (communityBubble && String(communityBubble).indexOf('<svg') >= 0) {
      var bbText = String(communityBubble).trim();
      if (bbText.length > 200000) {
        java.toast('气泡模板超过 ' + Math.round(200000/1024) + 'KB，已忽略（正文页将用默认气泡）');
        return;
      }
      SET('bbSvg', bbText);
      var bbKB = Math.round(bbText.length / 1024);
      java.toast('气泡社区已同步（' + bbKB + 'KB），请在正文页刷新' + (bbKB >= 30 ? '\n模板较大，章节缓存会相应增大' : ''));
    } else {
      java.toast('气泡社区暂无气泡，请先在社区网页选择');
    }
  } catch (e) {
    java.toast('气泡社区同步失败：\n' + e);
  }
}

function login_(openBrowser, checkMode) {
  var manual = '';
  try { manual = String((source.getLoginInfoMap() || {})['手动登录Token'] || '').trim(); } catch (e) {}
  var saved = String(cookie.getKey('fanqienovel.com', 'sessionid') || '').trim();
  if ((saved || manual) && !checkMode) {
    java.toast(manual ? '您为填写Token登录，请手动移除Token后再次登录' : '请不要重复登录，请先退出登录！');
    return false;
  }
  if (openBrowser) {
    try { java.startBrowserAwait('https://fanqienovel.com/', '登录'); } catch (e) { java.toast(e); }
  }
  try { cookie.removeCookie('snssdk.com'); } catch (e) {}
  var sessionid = String(cookie.getKey('fanqienovel.com', 'sessionid') || manual || '').trim();
  if (!sessionid) { java.toast('未获取到登录凭据，登录失败'); return false; }
  try {
    var root = requestJSON.call(this, '/api/book_user?sessionid=' + encodeURIComponent(sessionid));
    var user = root.data && (root.data.name || root.data.user_name || root.data.screen_name);
    if (!user) throw new Error('未返回用户信息');
    java.toast('欢迎 ' + user + '\n登录成功！');
    return true;
  } catch (e) { java.toast('登录检查失败：' + e); return false; }
}

