// 设置音色
function setVoice(num) {
    var data = _getTones();

    if (num < 0 || num >= data.length) { java.longToast("无效的接口编号！"); return; }
    SET('tone', data[num][1]);
    SET('tone_cn', data[num][0] + (GET('tone') ? '(' + GET('tone') + ')' : ''));
    java.longToast("设置成功\n当前模式：" + (GET('type') || "未知模式") + "\n音色设置：" + data[num][0] + (data[num][1] ? '[' + data[num][1] + ']' : '') + "\n‼️设置完成请点击切换模式‼️");
