      var forumId = String(forum.forum_id || '');
      if (forumId) {
        var commentRoot = requestJSON.call(this, '/api/end_comments?book_id=' + encodeURIComponent(bookId) + '&item_id=' + encodeURIComponent(itemId) + '&forum_id=' + encodeURIComponent(forumId) + '&count=30&offset=0');
        result.chapter = readerActionRows(commentRoot.data || commentRoot, ['mix_data','data_list','post_list','topic_list','comment_list','items','list'], 7).length;
      }
    } catch (chapterError) {}
  }
  if (enabled.author) {
    try {
      var authorRoot = requestJSON.call(this, '/api/author_say?book_id=' + encodeURIComponent(bookId) + '&item_id=' + encodeURIComponent(itemId));
      var authorPayload = authorRoot.data || authorRoot;
      var authorRows = readerActionRows(authorPayload, ['chapter_data_list','data_list','author_say_list','content_list','item_list'], 7)
        .filter(function(row) { return readerActionHasBody(row); });
      if (authorPayload.topic && readerActionHasBody(authorPayload.topic)) authorRows.push(authorPayload.topic);
      result.author = authorRows.length;
    } catch (authorError) {}
  }
  if (enabled.related) {
    try {
      var relatedRoot = requestJSON.call(this, '/api/recommendations?book_id=' + encodeURIComponent(bookId));
      var relatedPayload = relatedRoot.data || relatedRoot;
      result.related = Array.isArray(relatedPayload.book_info) ? relatedPayload.book_info.length : 0;
    } catch (relatedError) {}
  }
  return result;
}

