function parseTabItem(tabItem, fg) {
  var bookList = [];
  var videoList = [];

  if (!tabItem || typeof tabItem !== 'object') return [];

  function isArray(obj) {
    return Array.isArray(obj) || Object.prototype.toString.call(obj) === '[object JavaList]';
  }

  function walk(node) {
    if (!node || typeof node !== 'object') return;

    var i, len;

    if (isArray(node.book_data) && node.book_data.length > 0) {
      for (i = 0, len = node.book_data.length; i < len; i++) {
        var b = node.book_data[i];
        if (b && typeof b === 'object') bookList.push(b);
      }
    }

    if (isArray(node.video_data) && node.video_data.length > 0) {
      for (i = 0, len = node.video_data.length; i < len; i++) {
        var v = node.video_data[i];
        if (v && typeof v === 'object') videoList.push(v);
      }
    }

    if (isArray(node.cell_data)) {
      for (i = 0, len = node.cell_data.length; i < len; i++) {
        walk(node.cell_data[i]);
      }
    }

    if (isArray(node)) {
    	java.log('node')
      for (i = 0, len = node.length; i < len; i++) {
        walk(node[i]);
      }
    }
  }

