  cfg.hosts = normalizeHostLines(hostsValue);
  cfg.server = String(cfg.server || cfg.hosts[0] || '');
  cfg.server_id = Number(cfg.server_id || 0);
  cfg.api_key = keyValue;
  var cfgEncoded = encodeURIComponent(JSON.stringify(cfg));
  var hostsEncoded = escapeConfigHtml(encodeURIComponent(hostsValue));
  var keyEncoded = escapeConfigHtml(encodeURIComponent(keyValue));
  var css = '*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}'
    + 'body{margin:0;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,sans-serif;background:#f3f5f8;color:#1a1d23}'
    + '.wrap{padding:16px;max-width:720px;margin:0 auto}'
