@js:
  var res = [];
  function push(title, url, num, g, action) {
    var j = { title: title, url: url, style: { layout_flexGrow: g == 0 ? g : 1, layout_flexBasisPercent: num } };
    if (action) {
      j.action = action.action;
      j.name = action.name || title;
      j.type = action.type;
      j.chars = action.chars;
      j.viewName = action.viewName;
      j.default = action.default;
    }
    res.push(j);
  }
  // ---- 菜单分支：menu 经 FQ_SET/FQ_GET 存于源变量（jsLib 经 fqUseSource 桥接）----
  try { fqUseSource(source); } catch (eSrc) {}
  var menu = 'main';
  try { var m0 = FQ_GET('login_menu'); if (m0) { menu = String(m0); } } catch (eMenu) { menu = 'main'; }
  function go(m) { return "fqLvSetMenu('" + m + "')"; }
  function backBtn() { push('', '', 1, 1, { action: go('main'), name: '← 返回主菜单', type: 'button' }); }
  // 行尾占位符：每行 numx 个按钮，最后一排缺几个补几个（type=button 渲染为圆角块，不产生空输入框）
  function zwf(len, numx, num) {
    if (len % numx !== 0) {
      var p = numx - (len % numx);
      for (var i = 0; i < p; i++) { push('※', '', num, 1, { type: 'button', name: '※' }); }
    }
  }
  var d = fqLvState();
  var curMode = d.mode || '小说';
  var curTone = fqLvCurToneDisplay();
  var curToneName = curTone;
  for (var ti0 = 0; ti0 < FQLV_TONES.length; ti0++) { if (FQLV_TONES[ti0][1] === curTone) { curToneName = FQLV_TONES[ti0][0]; break; } }
  var MODE_ICONS = { '小说': '📗', '听书': '📻', '漫画': '🖼', '短剧': '📹', '漫剧': '🎬' };

  // ===== 分支：主菜单 =====
  if (menu === 'main') {
    res = [];
    push('⚙️ 状态', '', 1, 1, { action: 'fqLvToneInfo()', name: '模式：' + curMode + ' ｜ 🗣 音色：' + curToneName + (d.tone_custom ? ' [自定义]' : ''), type: 'button' });
    push('', '', 0.24, 1, { action: go('mode'), name: '📱 模式控制', type: 'button' });
    push('', '', 0.24, 1, { action: go('tone'), name: '🗣 音色设置', type: 'button' });
    push('', '', 0.24, 1, { action: go('para'), name: '💬 段评设置', type: 'button' });
    push('', '', 0.24, 1, { action: go('dev'), name: '📟 设备管理', type: 'button' });
    push('', '', 0.24, 1, { action: go('sys'), name: '🔧 系统帮助', type: 'button' });
    zwf(5, 3, 0.24);
  }

  // ===== 分支：模式控制 =====
  if (menu === 'mode') {
    res = [];
    var modeKeys = [];
    for (var mk in FQLV_MAP) { if (FQLV_MAP.hasOwnProperty(mk)) { modeKeys.push(mk); } }
    for (var mi = 0; mi < modeKeys.length; mi++) {
      var mname = modeKeys[mi];
      push('', '', 0.4, 1, { action: "fqLvSetMode('" + mname + "')", name: (MODE_ICONS[mname] || '') + mname, type: 'button' });
    }
    zwf(modeKeys.length, 2, 0.4);
    backBtn();
  }

  // ===== 分支：音色设置 =====
  if (menu === 'tone') {
    res = [];
    // 预设音色按钮（每行 4 个；点击时清除自定义音色）
    for (var ti = 0; ti < FQLV_TONES.length; ti++) {
      var tname = FQLV_TONES[ti][0], tid = FQLV_TONES[ti][1];
      push('', '', 0.24, 1, { action: "fqLvSetPresetTone('" + tid + "')", name: tname, type: 'button' });
    }
    // 自定义音色 ID 输入框 + 保存按钮（一行两个）
    push('自定义 toneId', '', 0.5, 1, { type: 'text', default: String(d.tone_custom || '') });
    push('', '', 0.3, 1, { action: 'fqLvSaveCustomTone()', name: '📥 保存自定义', type: 'button' });
    backBtn();
  }

  // ===== 分支：段评设置 =====
  if (menu === 'para') {
    res = [];
    push('气泡颜色', '', 0.4, 1, { type: 'text' });
    push('字体颜色', '', 0.4, 1, { type: 'text' });
    push('大小', '', 1, 1, { type: 'select', chars: ['TEXT', 'text'], default: 'text' });
    push('', '', 0.4, 1, { action: 'fqLvTogglePara()', name: (fqLvGetPara() === '1' ? '💬 ' : '🚫 ') + '段评：' + (fqLvGetPara() === '1' ? '已开启' : '已关闭'), type: 'button' });
    push('', '', 0.4, 1, { action: 'fqLvToggleSync()', name: (fqLvGetSync() === '1' ? '☁️ ' : '🚫 ') + '社区同步：' + (fqLvGetSync() === '1' ? '开' : '关'), type: 'button' });
    push('', '', 0.4, 1, { action: 'fqLvOpenCommunity()', name: '🎨 气泡社区', type: 'button' });
    push('', '', 0.4, 1, { action: "java.toast('气泡社区：选好气泡返回后，读正文时自动同步；关闭同步则恢复默认气泡')", name: '🎨 气泡：' + (fqLvState().bbSvg ? '已同步自定义' : '默认样式'), type: 'button' });
    backBtn();
  }

  // ===== 分支：设备管理 =====
  if (menu === 'dev') {
    res = [];
    push('', '', 0.4, 1, { action: 'fqLvPoolInfo()', name: '📋 设备池信息', type: 'button' });
    push('', '', 0.4, 1, { action: 'fqLvPoolClean()', name: '🗑 清空设备池', type: 'button' });
    backBtn();
  }

  // ===== 分支：系统与帮助 =====
  if (menu === 'sys') {
    res = [];
    push('', '', 0.4, 1, { action: 'fqLvBegan()', name: '🔄 初始化源变量', type: 'button' });
    push('', '', 0.4, 1, { action: "java.toast('模式也可在发现页下拉切换；点击预设音色会清除自定义音色。设备在构建时固定注入，本源不做设备注册。段评开关打开后正文段落末尾会显示评论数气泡，点击气泡可查看评论。气泡社区可自定义段评气泡样式。')", name: '帮助', type: 'button' });
    backBtn();
  }

  JSON.stringify(res);

