}

function qmExtractCaptionItems(c) {
  if (!c) return [];
  var it = c;
  if (c.data && c.data.list) it = c.data.list;
  else if (c.data && c.data.captions) it = c.data.captions;
  else if (c.data && c.data.sentences) it = c.data.sentences;
  else if (c.list) it = c.list;
  else if (c.captions) it = c.captions;
  else if (c.sentences) it = c.sentences;
  if (!it || !it.length) return [];
  return it
}

function qmExtractSubLines(i) {
  if (!i) return [];
  if (i.ss && i.ss.length) return i.ss;
  if (i.subtitles && i.subtitles.length) return i.subtitles;
  if (i.lines && i.lines.length) return i.lines;
  if (i.sentences && i.sentences.length) return i.sentences;
  if (i.items && i.items.length) return i.items;
  return [i]
}

function qmReadTime(c) {
  if (c == null) return NaN;
  var v = c.bt;
  if (v == null) v = c.begin;
  if (v == null) v = c.start;
  if (v == null) v = c.from;
  if (v == null) v = c.start_time;
  if (v == null) v = c.startTime;
  if (v == null) v = c.offset;
  if (v == null) v = c.time;
  if (v == null) return NaN;
