      var t = qmReadTime(ss[j]);
      if (!isNaN(t)) s.push(t)
    }
  }
  if (s.length < 2) return 'ms';
  s.sort(function(a, b) {
    return a - b
  });
  var mx = s[s.length - 1];
  if (mx < 1000) return 's';
  if (mx > 100000) return 'ms';
  var d = [];
  for (var k = 1; k < s.length; k++) {
    var x = s[k] - s[k - 1];
    if (x > 0) d.push(x)
  }
  if (!d.length) return 'ms';
  d.sort(function(a, b) {
    return a - b
  });
  var md = d[Math.floor(d.length / 2)];
