  var u = qmDetectUnit(it);
  var ls = [];

  function p(st, tx) {
    tx = String(tx || '').replace(/\r?\n/g, ' ').trim();
    if (!tx) return;
    var t = Number(st);
    if (isNaN(t)) t = 0;
    if (u === 's') t = t * 1000;
    var mn = Math.floor(t / 60000);
    var sc = Math.floor((t % 60000) / 1000);
    var cs = Math.floor((t % 1000) / 10);
    ls.push('[' + qmPadTime(mn) + ':' + qmPadTime(sc) + '.' + qmPadTime(cs) + ']' + tx)
  }
  for (var i = 0; i < it.length; i++) {
    var ss = qmExtractSubLines(it[i]);
    for (var j = 0; j < ss.length; j++) {
      p(qmReadTime(ss[j]), qmReadText(ss[j]))
    }
  }
  return ls.join('\n')
}

