    ['sys-ver', d.sys_ver],
    ['phone-level', d.phone_level],
    ['app_ver', d.app_version],
    ['imei', ''],
    ['model', d.model],
    ['wlb-imei', ''],
    ['wlb-uid', d.source_uid],
    ['client-id', d.source_uid],
    ['brand', d.brand],
    ['make', d.make],
    ['net_env', '1']
  ];
  var parts = fields.map(function(f) {
    return JSON.stringify(f[0]) + ':' + JSON.stringify(String(f[1]))
  });
  return qmC_ParamEncode.call(this, '{' + parts.join(',') + '}')
}

function qmC_HeaderSign(token, qp) {
  var values = {
    'AUTHORIZATION': token || '',
    'app-version': QM_C_APPV,
    'application-id': QM_C_APPID,
    'channel': QM_C_CHANNEL,
    'is-white': '0',
    'net-env': '1',
    'platform': 'android',
    'qm-params': qp,
    'reg': ''
  };
  var order = ['AUTHORIZATION', 'app-version', 'application-id', 'channel', 'is-white', 'net-env', 'platform', 'qm-params', 'reg'];
  var text = '';
  order.forEach(function(k) {
    text += k + '=' + values[k]
  });
  return qmC_Sign.call(this, text)
}

function qmC_Headers(token) {
  var src = qmC_SourceOf.call(this);
  var d = qmC_Device.call(this);
  var qp = qmC_BuildParams.call(this, d);
  var now = Math.floor(Date.now() / 1000);
  var uid = String(src.get('qm_c_uid') || '');
  return {
    'authorization': token || '',
    'app-version': QM_C_APPV,
    'application-id': QM_C_APPID,
    'channel': QM_C_CHANNEL,
    'is-white': '0',
    'net-env': '1',
    'platform': 'android',
    'qm-params': qp,
    'reg': '',
    'sign': qmC_HeaderSign.call(this, token || '', qp),
    'qm-uaf': qmC_Day() + '-' + uid,
    'qm-it': String(now),
    'qm-ii': String(now % 10000000000),
    'no-permiss': '3',
    'user-agent': 'webviewversion/0',
    'qm-request-id': qmC_Sign.call(this, String(Date.now()) + qmC_RandomHex.call(this, 8))
  }
}

function qmC_Login() {
  var src = qmC_SourceOf.call(this);
  var token = String(src.get('qm_c_token') || '');
  var exp = Number(src.get('qm_c_exp') || 0);
  if (token && exp > Math.floor(Date.now() / 1000) + 60) return token;
  try {
    var form = {
      cancell_check: '1',
      gender: '0'
    };
    form.sign = qmC_UrlSign.call(this, form);
    var headers = qmC_Headers.call(this, '');
    headers['content-type'] = 'application/x-www-form-urlencoded';
    var option = {
      method: 'POST',
      headers: headers,
      body: qmC_Form(form)
    };
    var resp = JSON.parse(String(qmC_JavaOf.call(this).ajax('https://xiaoshuo.wtzw.com/api/v1/login/tourist,' + JSON.stringify(option)) || '{}'));
    token = String((resp && resp.data && resp.data.token) || '');
    if (!token) return '';
    src.put('qm_c_token', token);
    src.put('qm_c_exp', String(Math.floor(Date.now() / 1000) + 3600))
  } catch (e) {
    return ''
  }
  return token
}

function qmC_Request(method, url, params, form) {
  var j = qmC_JavaOf.call(this);
  var token = qmC_Login.call(this);
  var option = {
    method: method,
    headers: qmC_Headers.call(this, token)
  };
  if (form) {
    var body = {};
    Object.keys(form || {}).forEach(function(k) {
      body[k] = String(form[k])
    });
    body.sign = qmC_UrlSign.call(this, body);
    option.headers['content-type'] = 'application/x-www-form-urlencoded';
    option.body = qmC_Form(body)
  } else {
    var query = {};
    Object.keys(params || {}).forEach(function(k) {
      query[k] = String(params[k])
    });
    var parts = Object.keys(query).sort().map(function(k) {
      return encodeURIComponent(k) + '=' + encodeURIComponent(query[k])
    });
    parts.push('sign=' + qmC_UrlSign.call(this, query));
    url += '?' + parts.join('&')
  }
  return JSON.parse(String(j.ajax(url + ',' + JSON.stringify(option)) || '{}'))
}

function qmC_Get(url, params) {
  return qmC_Request.call(this, 'GET', url, params, null)
}

function qmC_PostForm(url, form) {
  return qmC_Request.call(this, 'POST', url, {}, form)
}

function qmC_Esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}

