}

function getToken(_) {
    var ctx = _ || this;
    var java = ctx.java;
    var source = ctx.source;
    var cache = ctx.cache;
    var key = source.getKey();
    var token = cache.getFromMemory(key + "_token");
    var refreshToken = cache.getFromMemory(key + "_refreshToken");
    var tokenTime = cache.getFromMemory(key + "_tokenTime");
    var now = Date.now();
    if (token && refreshToken && tokenTime && (now - Number(tokenTime)) < 1800000) return;
    java.log("获取token中");
    var rn = getRandomString(10);
    var md5str = "0UYHMKJ%$#&21918djduw^&*()_+^$%kjdsk28dkdj236^" + rn + "6.10.95.800009%2Fdata%2Fuser%2F0%2Fcom.tadu.read%2Ffiles%2F101080*2029MI8";
    var desKey = java.md5Encode(md5str);
    var desRes = java.createSymmetricCrypto("DES/ECB/PKCS5Padding", "LAP^%O$8").encryptHex(desKey).toUpperCase();
    var h = { "cookie": "sessionid=;token=;refreshToken=;bearer=" + getBarer(ctx) };
    h["x-client"] = "sdk=10;sdkVersion=29;screenSize=1080*2029;type=MI8;imei=;imsi=;version=6.10.95.800009;versionCode=1315;rootPath=%2Fdata%2Fuser%2F0%2Fcom.tadu.read%2Ffiles%2F;rn=" + rn + ";tdcn=" + desRes + ";android_id_new=2179ceffede388e8;localTime=1741575579972;shuZiId=;tdUUID=" + java.randomUUID() + ";oaid=f1a07127cc32ede2;isGuestMode=0;readLike=0;tagIds=;make=Xiaomi;package_name=zhuishu;k=;";
    var url = "https://reader.tadu.com/user/api/register," + JSON.stringify({ headers: h, method: "POST", body: "readType=0" });
    java.log(url);
    var res = JSON.parse(java.ajax(url));
    java.log(res);
    token = res.data.token;
    refreshToken = res.data.refreshToken;
    if (token && refreshToken) {
        cache.putMemory(key + "_token", token);
        cache.putMemory(key + "_refreshToken", refreshToken);
        cache.putMemory(key + "_tokenTime", String(now));
        java.log("获取token成功");
    }
}

function getBarer(_) {
    var ctx = _ || this;
    var java = ctx.java;
    var timestamp = new Date().getTime();
    var p = { "clientTime": timestamp, "iat": Math.floor(timestamp / 1000) };
    var aeskey = b(timestamp, 16);
    p.sdk = aesEncode("29", aeskey, ctx);
    p.sessionid = aesEncode("11f316d6a4da4013be3eac2058995e77", aeskey, ctx);
    p.iss = "tadu:app:android:" + aeskey;
    p.jti = java.md5Encode(aesEncode("cd2yj5352pu927mrsn5kmut0saloniy", aeskey, ctx) + ":" + aesEncode(p.iss, aeskey, ctx) + ":" + aesEncode(String(timestamp), aeskey, ctx).toLowerCase());
    var mds = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9." + java.base64Encode(JSON.stringify(p));
    var hmac = java.HMacHex(mds, "HmacSHA256", "1a8154132fg4a784fad101661z1854181ac1qed7");
    hmac = Packages.java.util.Base64.getEncoder().encodeToString(java.hexDecodeToByteArray(hmac));
    return java.base64Encode(mds + "." + toUrlSafeBase64(hmac));
}

function b(n, size) {
    var a = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    var sb = [];
    while (n > 61) {
        sb.push(a.charAt(n % 62));
        n = Math.floor(n / 62);
    }
    sb.push(a.charAt(n));
    return sb.reverse().join("").padStart(size, "0");
}

function aesEncode(str, key, _) {
    return (_ || this).java.createSymmetricCrypto("AES/ECB/PKCS5Padding", key).encryptBase64(str);
}

function toUrlSafeBase64(s) {
    return String(s).replace(/\+/g, "-").replace(/\//g, "_");
}

