ruleContent.content:
@js:
var hexStr = "";
try { hexStr = java.hexDecodeToString(result); } catch(e) { hexStr = ""; }
if (!hexStr) { "章节链接解析失败"; }
var taduData = org.jsoup.Jsoup.connect("https://media3.tadu.com/" + hexStr)
    .ignoreContentType(true)
    .ignoreHttpErrors(true)
    .execute()
    .bodyAsBytes();

var javaImport = new JavaImporter();
javaImport.importPackage(
    Packages.java.io,
    Packages.java.util.zip,
    Packages.java.lang,
    Packages.java.nio
);

with (javaImport) {
    function createBytes(n) {
        return ByteBuffer.allocate(n).array();
    }
    function parseTadu(data) {
        var bis = new BufferedInputStream(new ByteArrayInputStream(data));
        try {
            var header = createBytes(4);
            if (bis.read(header) != 4) {
                throw new IOException("不是合法的 tadu 文件");
            }
            bis.skip(4);
            var skipBytes = createBytes(8);
            if (bis.read(skipBytes) != 8) {
                throw new IOException("文件格式错误，无法读取跳过字节数");
            }
            var skipLength = ((skipBytes[1] & 0xFF) << 8) | (skipBytes[0] & 0xFF);
            bis.skip(skipLength);
            bis.skip(16);
            var gis = new GZIPInputStream(bis);
            var baos = new ByteArrayOutputStream();
            var buffer = createBytes(4096);
            var len;
            while ((len = gis.read(buffer)) > 0) {
                baos.write(buffer, 0, len);
            }
            return decodeUtf16(baos.toByteArray());
        } finally {
            bis.close();
        }
    }
}

function decodeUtf16(data) {
    var arr = [];
    for (var i = 0; i < data.length; i += 2) {
        if (i + 1 >= data.length) break;
        var b1 = data[i] & 0xFF;
        var b2 = data[i + 1] & 0xFF;
        if (b1 === 0xFF && b2 === 0xFE) {
            continue;
        } else if (b1 === 0x0D && b2 === 0x00) {
            arr.push(' ');
        } else {
            arr.push(String.fromCharCode((b2 << 8) | b1));
        }
    }
    return arr.join('');
}

parseTadu(taduData);

